    public static int match_game(List<int[]> arr1, List<int[]> arr2) {
        int score = 0;
        int[] c1 = new int[2];
        int[] c2 = new int[2];
        boolean c1_valid = false;
        boolean c2_valid = false;

        while (!arr1.isEmpty() || !arr2.isEmpty()) {
