public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int round = Integer.parseInt(scanner.nextLine().trim());
        String[] firstpersonInput = scanner.nextLine().trim().split(" ");
        String[] secondpersonInput = scanner.nextLine().trim().split(" ");

        int[] firstperson = new int[3];
        int[] secondperson = new int[3];

        for (int i = 0; i < 3; i++) {
            firstperson[i] = Integer.parseInt(firstpersonInput[i]);
            secondperson[i] = Integer.parseInt(secondpersonInput[i]);
        }

        solve(round, firstperson, secondperson);
    }

    public static void solve(int round, int[] firstperson, int[] secondperson) {
        // find max win
        int win = 0;
        int[] secondpersonCopy = Arrays.copyOf(secondperson, 4);
        secondpersonCopy[3] = secondpersonCopy[0];

        for (int i = 0; i < 3; i++) {
            int findless = Math.min(firstperson[i], secondpersonCopy[i + 1]);
            win += findless;
        }

        // find min win
        int[] secondpersonForMin = new int[4];
        secondpersonForMin[0] = secondperson[2];
        secondpersonForMin[1] = secondperson[0];
        secondpersonForMin[2] = secondperson[1];
        secondpersonForMin[3] = secondperson[2];

        int[] firstpersonCopy = Arrays.copyOf(firstperson, 3);

        for (int i = 0; i < 3; i++) {
            if (firstpersonCopy[i] > 0) {
                int diff = Math.min(firstpersonCopy[i], secondpersonForMin[i]);
                firstpersonCopy[i] -= diff;
                secondpersonForMin[i] -= diff;

                if (firstpersonCopy[i] > 0) {
                    diff = Math.min(firstpersonCopy[i], secondpersonForMin[i + 1]);
                    firstpersonCopy[i] -= diff;
                    secondpersonForMin[i + 1] -= diff;
                }
            }
        }

        int minWin = firstpersonCopy[0] + firstpersonCopy[1] + firstpersonCopy[2];

        System.out.println(minWin + " " + win);
    }
}

