        }
        for (int i = 0; i < 3; i++) {
            b[i] = scanner.nextInt();
        }

        int r1 = a[0], s1 = a[1], p1 = a[2];
        int r2 = b[0], s2 = b[1], p2 = b[2];

        int max_possible = computeMaxWins(r1, s1, p1, r2, s2, p2);
        int min_possible = computeMinWins(r1, s1, p1, r2, s2, p2);

        System.out.println(min_possible + " " + max_possible);
    }

    public static int computeMinWins(int r1, int s1, int p1, int r2, int s2, int p2) {
        int[] r = {r1, s1, p1};
        int[] opp = {r2, s2, p2};

        int max_wins = Math.min(r[0], opp[2]) + Math.min(r[1], opp[0]) + Math.min(r[2], opp[1]);
        return max_wins;
    }

    public static int computeMaxWins(int r1, int s1, int p1, int r2, int s2, int p2) {
        int[] r = {r1, s1, p1};
        int[] opp = {r2, s2, p2};
        int total_wins = 0;

        for (int i = 0; i < 3; i++) {
            int same = Math.min(r[i], opp[i]);
            r[i] -= same;
            opp[i] -= same;
        }

        if (r[0] > 0) {
            int use = Math.min(r[0], opp[2]);
            total_wins += use;
            r[0] -= use;
            opp[2] -= use;
        }

        if (r[1] > 0) {
            int use = Math.min(r[1], opp[0]);
            total_wins += use;
            r[1] -= use;
            opp[0] -= use;
        }

        if (r[2] > 0) {
            int use = Math.min(r[2], opp[1]);
            total_wins += use;
            r[2] -= use;
            opp[1] -= use;
        }

        return total_wins;
    }
