public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int rounds = scanner.nextInt();
        int[] first = new int[3];
        int[] second = new int[3];

        for (int i = 0; i < 3; i++) {
            first[i] = scanner.nextInt();
        }
        for (int i = 0; i < 3; i++) {
            second[i] = scanner.nextInt();
        }

        int[] result = processMatches(first[0], first[1], first[2], second[0], second[1], second[2]);
        System.out.println(result[0] + " " + result[1]);
    }

    public static int[] processMatches(int r1, int s1, int p1, int r2, int s2, int p2) {
        // Calculate the best-case scenario (maximum wins)
        int bestWins = 0;
        // Use rock to beat scissors
        int rockVsScissors = Math.min(r1, p2);
        bestWins += rockVsScissors;
        r1 -= rockVsScissors;
        p2 -= rockVsScissors;
        // Use paper to beat rock
        int paperVsRock = Math.min(p1, r2);
        bestWins += paperVsRock;
        p1 -= paperVsRock;
        r2 -= paperVsRock;
        // Use scissors to beat paper
        int scissorsVsPaper = Math.min(s1, s2);
        bestWins += scissorsVsPaper;
        s1 -= scissorsVsPaper;
        s2 -= scissorsVsPaper;

        // Now calculate worst-case scenario (minimum wins remaining after optimal matching)
        // Build a simulation of residual counts after optimal match
        int[] rRem = {r1, s1, p1};
        int[] oppRem = {r2, s2, p2};

        // First eliminate same-type matchups (draws)
        for (int i = 0; i < 3; i++) {
            int match = Math.min(rRem[i], oppRem[i]);
            rRem[i] -= match;
            oppRem[i] -= match;
        }

        // Then try to convert remaining to wins
        // Rock(0) beats scissors(2), paper(1) beats rock(0), scissors(2) beats paper(1)
        int totalMinWins = 0;
        // Try rock vs scissors
        if (rRem[0] > 0 && oppRem[2] > 0) {
            int use = Math.min(rRem[0], oppRem[2]);
            totalMinWins += use;
            rRem[0] -= use;
            oppRem[2] -= use;
        }
        // Try paper vs rock
        if (rRem[1] > 0 && oppRem[0] > 0) {
            int use = Math.min(rRem[1], oppRem[0]);
            totalMinWins += use;
            rRem[1] -= use;
            oppRem[0] -= use;
        }
        // Try scissors vs paper
        if (rRem[2] > 0 && oppRem[1] > 0) {
            int use = Math.min(rRem[2], oppRem[1]);
            totalMinWins += use;
            rRem[2] -= use;
            oppRem[1] -= use;
        }

        return new int[]{totalMinWins, bestWins};
    }
}

