        }

        int[] result = calculateResult(
            first_moves[0], first_moves[1], first_moves[2],
            second_moves[0], second_moves[1], second_moves[2]
        );

        System.out.println(result[0] + " " + result[1]);
    }

    public static int[] calculateResult(int r1, int s1, int p1, int r2, int s2, int p2) {
        // Initialize counts
        int r1_count = r1, s1_count = s1, p1_count = p1;
        int r2_count = r2, s2_count = s2, p2_count = p2;

        // Calculate maximum wins (best case for first person)
        int best = 0;

        // Use rock against scissors
        int rockVsScissors = Math.min(r1_count, p2_count);
        best += rockVsScissors;
        int remaining_r1 = r1_count - rockVsScissors;
        int remaining_p2 = p2_count - rockVsScissors;

        // Use paper against rock
        int paperVsRock = Math.min(p1_count, r2_count);
        best += paperVsRock;
        int remaining_p1 = p1_count - paperVsRock;
        int remaining_r2 = r2_count - paperVsRock;

        // Use scissors against paper
        int scissorsVsPaper = Math.min(s1_count, s2_count);
        best += scissorsVsPaper;
        int remaining_s1 = s1_count - scissorsVsPaper;
        int remaining_s2 = s2_count - scissorsVsPaper;

        // Now calculate minimum wins (worst case)
        // Try to minimize wins by using moves that cause draws first
        // First eliminate same-type matches (draws)
        int r1_min = r1, s1_min = s1, p1_min = p1;
        int r2_min = r2, s2_min = s2, p2_min = p2;

        int drawRock = Math.min(r1_min, r2_min);
        r1_min -= drawRock;
        r2_min -= drawRock;

        int drawPaper = Math.min(p1_min, p2_min);
        p1_min -= drawPaper;
        p2_min -= drawPaper;

        int drawScissors = Math.min(s1_min, s2_min);
        s1_min -= drawScissors;
        s2_min -= drawScissors;

        // Now try to convert remaining to wins
        int worst = 0;

        // After draws, use remaining rock against scissors if possible
        if (r1_min > 0 && p2_min > 0) {
            int use = Math.min(r1_min, p2_min);
            worst += use;
            r1_min -= use;
            p2_min -= use;
        }

        // Use remaining paper against rock if possible
        if (p1_min > 0 && r2_min > 0) {
            int use = Math.min(p1_min, r2_min);
            worst += use;
            p1_min -= use;
            r2_min -= use;
        }

        // Use remaining scissors against paper if possible
        if (s1_min > 0 && s2_min > 0) {
            int use = Math.min(s1_min, s2_min);
            worst += use;
            s1_min -= use;
            s2_min -= use;
        }

        return new int[]{worst, best};
    }
}

