    private static int[] solveGame(int r1, int s1, int p1, int r2, int s2, int p2) {
        // Calculate maximum wins
        int maxWins = 0;

        // Rock(0) beats scissors(p2), Paper(1) beats rock(r2), Scissors(2) beats paper(s2)
        int win1 = Math.min(r1, s2);
        maxWins += win1;
        int tmpR1 = r1 - win1;
