                                  secondInput[0], secondInput[1], secondInput[2]);

        System.out.println(result[0] + " " + result[1]);
    }

    public static int[] solveLogic(int r1, int s1, int p1, int r2, int s2, int p2) {
        // First compute maximum wins: optimal arrangement
        int maxWin = 0;

        // Rock beats scissors, so r1 vs p2
        int winRock = Math.min(r1, p2);
        maxWin += winRock;
        r1 -= winRock;
        p2 -= winRock;

        // Paper beats rock, so p1 vs r2
        int winPaper = Math.min(p1, r2);
        maxWin += winPaper;
        p1 -= winPaper;
        r2 -= winPaper;

        // Scissors beats paper, so s1 vs s2
        int winScissors = Math.min(s1, s2);
        maxWin += winScissors;
        s1 -= winScissors;
        s2 -= winScissors;

        // For minimum wins: eliminate draws first, then count residual wins
        // Eliminate same moves (draws)
        int drawRock = Math.min(r1, r2);
        r1 -= drawRock;
        r2 -= drawRock;

        int drawScissors = Math.min(s1, s2);
        s1 -= drawScissors;
        s2 -= drawScissors;

        int drawPaper = Math.min(p1, p2);
        p1 -= drawPaper;
        p2 -= drawPaper;

        // Now compute minimum wins by matching leftovers smartly
        int minWin = 0;

        // Try all possible leftover combinations
        // After eliminating draws, remaining are only mismatched moves
        // Try rock vs scissors, paper vs rock, scissors vs paper
        while (r1 > 0 && s2 > 0) {
            int use = Math.min(r1, s2);
            minWin += use;
            r1 -= use;
            s2 -= use;
        }

        while (p1 > 0 && r2 > 0) {
            int use = Math.min(p1, r2);
            minWin += use;
            p1 -= use;
            r2 -= use;
        }

        while (s1 > 0 && p2 > 0) {
            int use = Math.min(s1, p2);
            minWin += use;
            s1 -= use;
            p2 -= use;
        }

        return new int[]{minWin, maxWin};
    }
}

