import java.io.*;
import java.util.*;

public class Main {
    private static InputStream fin;
    private static OutputStream fout;
    private static PrintStream originalStdout;
    private static boolean varForSublime = false;

    public static void main(String[] args) {
        originalStdout = System.out;

        if (varForSublime) {
            try {
                fin = new FileInputStream("input.txt");
                fout = new FileOutputStream("output.txt");
                System.setOut(new PrintStream(fout));
            } catch (FileNotFoundException e) {
                throw new RuntimeException(e);
            }
        } else {
            fin = System.in;
            fout = System.out;
        }

        try {
            HeyYashwant();
        } finally {
            try {
                fin.close();
                fout.close();
                System.setOut(originalStdout);
            } catch (IOException e) {
                // ignore
            }
        }
    }

    private static String giveString() {
        try {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = fin.read()) != -1 && c != '\n' && c != '\r') {
                sb.append((char) c);
            }
            // Skip line ending characters
            if (fin.available() > 0) {
                int next = fin.read();
                if (next == '\r' && fin.available() > 0) {
                    fin.read(); // skip \n after \r
                }
            }
            return sb.toString().trim();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static List<Integer> giveList() {
        String[] parts = giveString().split("\\s+");
        List<Integer> list = new ArrayList<>();
        for (String part : parts) {
            list.add(Integer.parseInt(part));
        }
        return list;
    }

    private static int giveInt() {
        return Integer.parseInt(giveString());
    }

    private static final long MOD = 1000000007;

    private static long modpow(long a, long p) {
        long ans = 1;
        while (p > 0) {
            if ((p & 1) == 1) {
                ans = (ans * a) % MOD;
            }
            p >>= 1;
            a = (a * a) % MOD;
        }
        return ans;
    }

    private static long facCal(int n) {
        long ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = (ans * i) % MOD;
        }
        return ans;
    }

    private static void solve() {
        int t = 1;
        List<List<Integer>> l = new ArrayList<>();
        int[] base = {1, 2, 3, 4, 5, 6};
        permute(base, 0, l);

        int n = giveInt();
        List<Integer> aList = giveList();
        List<Integer> bList = giveList();

        int a1 = aList.get(0), a2 = aList.get(1), a3 = aList.get(2);
        int b1 = bList.get(0), b2 = bList.get(1), b3 = bList.get(2);

        int mx = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);
        int temp = 0;

        for (List<Integer> per : l) {
            int ta1 = a1, ta2 = a2, ta3 = a3;
            int tb1 = b1, tb2 = b2, tb3 = b3;
            int tmx = 0;

            for (int el : per) {
                if (el == 1) {
                    int t1 = Math.min(ta1, tb1);
                    ta1 -= t1;
                    tb1 -= t1;
                    tmx += t1;
                } else if (el == 2) {
                    int t1 = Math.min(ta1, tb3);
                    ta1 -= t1;
                    tb3 -= t1;
                    tmx += t1;
                } else if (el == 3) {
                    int t1 = Math.min(ta2, tb2);
                    ta2 -= t1;
                    tb2 -= t1;
                    tmx += t1;
                } else if (el == 4) {
                    int t1 = Math.min(ta2, tb1);
                    tb1 -= t1;
                    ta2 -= t1;
                    tmx += t1;
                } else if (el == 5) {
                    int t1 = Math.min(ta3, tb3);
                    ta3 -= t1;
                    tb3 -= t1;
                    tmx += t1;
                } else if (el == 6) {
                    int t1 = Math.min(ta3, tb2);
                    tb2 -= t1;
                    ta3 -= t1;
                    tmx += t1;
                }
            }
            temp = Math.max(temp, tmx);
        }

        System.out.print((n - temp) + " ");
        System.out.println(mx);
    }

    private static void permute(int[] arr, int k, List<List<Integer>> result) {
        for (int i = k; i < arr.length; i++) {
            swap(arr, i, k);
            permute(arr, k + 1, result);
            swap(arr, k, i);
        }
        if (k == arr.length - 1) {
            List<Integer> list = new ArrayList<>();
            for (int val : arr) {
                list.add(val);
            }
            result.add(list);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private static void HeyYashwant() {
        try {
            int t = 1;
            // t = giveInt();
            for (int i = 0; i < t; i++) {
                solve();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

