        int a1 = a[0], a2 = a[1], a3 = a[2];
        int b1 = b[0], b2 = b[1], b3 = b[2];

        int max_possible = Math.min(a1, b2) + Math.min(a2, b3) + Math.min(a3, b1);

        int best_match = 0;
        int[] perm = {1, 2, 3, 4, 5, 6};

        // Generate all permutations using Heap's algorithm
        permute(perm, 0, perm.length - 1, a1, a2, a3, b1, b2, b3);

        // We need to calculate best_match during permutation generation
        // Since Java doesn't have itertools.permutations, we'll use a different approach
        // Let's manually compute all 720 permutations
        best_match = calculateBestMatch(a1, a2, a3, b1, b2, b3);

        out.println((n - best_match) + " " + max_possible);
    }

    private static int calculateBestMatch(int a1, int a2, int a3, int b1, int b2, int b3) {
        int best_match = 0;
        int[] perm = {1, 2, 3, 4, 5, 6};

        // Generate all permutations using Heap's algorithm
        List<int[]> allPerms = new ArrayList<>();
        permuteToList(perm, 0, perm.length - 1, allPerms);

        for (int[] p : allPerms) {
            int ta1 = a1, ta2 = a2, ta3 = a3;
            int tb1 = b1, tb2 = b2, tb3 = b3;
            int current_match = 0;

            for (int val : p) {
                if (val == 1) {
                    int t = Math.min(ta1, tb1);
                    ta1 -= t;
                    tb1 -= t;
                    current_match += t;
                } else if (val == 2) {
                    int t = Math.min(ta1, tb3);
                    ta1 -= t;
                    tb3 -= t;
                    current_match += t;
                } else if (val == 3) {
                    int t = Math.min(ta2, tb2);
                    ta2 -= t;
                    tb2 -= t;
                    current_match += t;
                } else if (val == 4) {
                    int t = Math.min(ta2, tb1);
                    ta2 -= t;
                    tb1 -= t;
                    current_match += t;
                } else if (val == 5) {
                    int t = Math.min(ta3, tb3);
                    ta3 -= t;
                    tb3 -= t;
                    current_match += t;
                } else if (val == 6) {
                    int t = Math.min(ta3, tb2);
                    ta3 -= t;
                    tb2 -= t;
                    current_match += t;
                }
            }

            best_match = Math.max(best_match, current_match);
        }

        return best_match;
    }

    private static void permuteToList(int[] arr, int start, int end, List<int[]> result) {
        if (start == end) {
            result.add(arr.clone());
        } else {
            for (int i = start; i <= end; i++) {
                swap(arr, start, i);
                permuteToList(arr, start + 1, end, result);
                swap(arr, start, i);
            }
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private static void permute(int[] arr, int l, int r) {
        if (l == r) {
            // Process permutation
        } else {
            for (int i = l; i <= r; i++) {
                swap(arr, l, i);
                permute(arr, l + 1, r);
                swap(arr, l, i);
            }
        }
    }
}

