import java.util.*;
import java.io.*;

public class Main {

    static class Dinic {
        static final long INF = (long) 1e18;
        int n;
        List<List<long[]>> links;
        int[] depth;
        int[] progress;
        List<int[]> pos;

        public Dinic(int n) {
            this.n = n;
            this.links = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                links.add(new ArrayList<>());
            }
            this.depth = null;
            this.progress = null;
            this.pos = new ArrayList<>();
        }

        public Dinic copy() {
            Dinic res = new Dinic(this.n);
            for (int i = 0; i < n; i++) {
                for (long[] a : links.get(i)) {
                    res.links.get(i).add(Arrays.copyOf(a, a.length));
                }
            }
            for (int[] a : pos) {
                res.pos.add(Arrays.copyOf(a, a.length));
            }
            return res;
        }

        public void add_edge(int _from, int to, long cap) {
            pos.add(new int[]{_from, links.get(_from).size()});
            links.get(_from).add(new long[]{cap, to, links.get(to).size()});
            links.get(to).add(new long[]{0, _from, links.get(_from).size() - 1});
        }

        public void bfs(int s) {
            depth = new int[n];
            Arrays.fill(depth, -1);
            depth[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int v = q.poll();
                for (long[] edge : links.get(v)) {
                    int to = (int) edge[1];
                    if (edge[0] > 0 && depth[to] < 0) {
                        depth[to] = depth[v] + 1;
                        q.offer(to);
                    }
                }
            }
        }

        public long dfs(int v, int t, long flow) {
            if (v == t) {
                return flow;
            }
            List<long[]> links_v = links.get(v);
            for (int i = progress[v]; i < links_v.size(); i++) {
                progress[v] = i;
                long[] link = links_v.get(i);
                long cap = link[0];
                int to = (int) link[1];
                int rev = (int) link[2];
                if (cap == 0 || depth[v] >= depth[to]) {
                    continue;
                }
                long d = dfs(to, t, Math.min(flow, cap));
                if (d == 0) {
                    continue;
                }
                link[0] -= d;
                links.get(to).get(rev)[0] += d;
                return d;
            }
            return 0;
        }

        public long flow(int s, int t) {
            long flow = 0;
            while (true) {
                bfs(s);
                if (depth[t] < 0) {
                    return flow;
                }
                progress = new int[n];
                long current_flow = dfs(s, t, INF);
                while (current_flow > 0) {
                    flow += current_flow;
                    current_flow = dfs(s, t, INF);
                }
            }
        }

        public long[] getEdge(int i) {
            int[] p = pos.get(i);
            long[] e = links.get(p[0]).get(p[1]);
            long[] re = links.get((int) e[1]).get((int) e[2]);
            long[] res = new long[4];
            res[0] = p[0];
            res[1] = e[1];
            res[2] = e[0] + re[0];
            res[3] = re[0];
            return res;
        }

        public List<long[]> getEdges() {
            int M = pos.size();
            List<long[]> res = new ArrayList<>();
            for (int i = 0; i < M; i++) {
                res.add(getEdge(i));
            }
            return res;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = br.readLine().trim().split(" ");
        int N = Integer.parseInt(line1[0]);
        int M = 3;
        String[] line2 = br.readLine().trim().split(" ");
        int[] A = new int[M];
        for (int i = 0; i < M; i++) {
            A[i] = Integer.parseInt(line2[i]);
        }
        String[] line3 = br.readLine().trim().split(" ");
        int[] B = new int[M];
        for (int i = 0; i < M; i++) {
            B[i] = Integer.parseInt(line3[i]);
        }

        int ans1 = 0;
        for (int i = 0; i < M; i++) {
            ans1 += Math.min(A[i], B[(i + 1) % M]);
        }

        int ans2 = 0;
        Dinic dinic = new Dinic(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;
        for (int i = 0; i < M; i++) {
            dinic.add_edge(s, i, N);
            dinic.add_edge(M + i, t, B[i]);
            dinic.add_edge(i, M + i, A[i]);
