            int prev = num;
            int k = 1;
            while (k <= num / max_f) {
                int next_q = num / (k + 1);
                int count = prev - next_q;
                total = (total + count * mem[k]) % mod;
                prev = next_q;
                k++;
            }

            mem[num] = total;
        }

        System.out.println(n > 0 ? mem[n] % mod : 0);
    }
}

