            while (multiple <= n) {
                D.get(multiple).add(divisor);
                multiple += divisor;
            }
        }

        // Dynamic programming array
        long[] F = new long[n + 1];
        F[1] = 1;
        F[2] = 2;

        // Fill F array
        for (int value = 3; value <= n; value++) {
            // Compute the recurrence relation
            F[value] = (2 * F[value - 1]) % M;
            F[value] = (F[value] + F[value / (value - 1)]) % M;

            // Add contributions from divisors
            for (int d : D.get(value)) {
                if (2 <= d && d <= value - 2) {
                    F[value] = (F[value] + F[value / d] - F[(value - 1) / d]) % M;
                }
            }
        }

        // Ensure non-negative result
        long result = F[n] % M;
        if (result < 0) {
            result += M;
        }
        System.out.println(result);
    }
}

