public class Main {
    static final long MOD = 1000000007;

    public static void process() {
        Scanner sc = new Scanner(System.in);
        int P = sc.nextInt();
        int K = sc.nextInt();

        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            k[x] = (int) ((long) K * x % P);
        }

        if (K == 0) {
            System.out.println(powMod(P, P - 1, MOD));
            return;
        }
        if (K == 1) {
            System.out.println(powMod(P, P, MOD));
            return;
        }

        int[] f = new int[P];
        int[] c = new int[P];
        long ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i] != 0) continue;

            int cnt = 1;
            int u = i;
            f[u] = 1;
            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 2; i < P; i++) {
            if (c[i] != 0) {
                long cnt = (long) i * c[i] + 1;
                ans = ans * powMod(cnt, c[i], MOD) % MOD;
            }
        }

        System.out.println(ans);
    }

    static long powMod(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        int T = 1;
        for (int i = 0; i < T; i++) {
            process();
        }
    }
}

