        long finalVal = 1;

        for (int start = 0; start < P; start++) {
            if (marked[start]) {
                continue;
            }

            // Walk through the cycle
            int steps = 0;
            int current = start;
            while (!marked[current]) {
                marked[current] = true;
                current = transform[current];
                steps++;
            }

            if (steps > 0) {
                cycleCounter[steps]++;
            }
        }

        // Calculate result using cycle data
        for (int size = 2; size < P; size++) {
            int occurrences = cycleCounter[size];
            if (occurrences > 0) {
                long temp = (long) size * occurrences + 1;
                finalVal = (finalVal * modPow(temp, occurrences, MOD)) % MOD;
            }
        }

        System.out.println(finalVal);
    }

    static long modPow(long base, long exponent, long mod) {
        long result = 1;
        base = base % mod;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exponent >>= 1;
        }
        return result;
    }
}

