public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = 1;
        for (int t = 0; t < T; t++) {
            process(sc);
        }
    }

    static void process(Scanner sc) {
        int P = sc.nextInt();
        int K = sc.nextInt();

        int[] k = new int[P];
        for (int x = 0; x < P; x++) {
            k[x] = (int) ((long) K * x % P);
        }

        if (K == 0) {
            System.out.println(pow(P, P - 1, MOD));
            return;
        }

        int[] f = new int[P];
        long[] c = new long[P];
        long ans = 1;

        for (int i = 0; i < P; i++) {
            if (f[i] != 0) continue;

            int cnt = 1;
            int u = i;
            f[u] = 1;
            while (f[k[u]] == 0) {
                u = k[u];
                f[u] = 1;
                cnt++;
            }

            c[cnt]++;
        }

        for (int i = 1; i < P; i++) {
            if (c[i] != 0) {
                long cnt = (long) i * c[i] + (i > 1 ? 1 : 0);
                ans = ans * pow(cnt, c[i], MOD) % MOD;
            }
        }

        System.out.println(ans);
    }

    static long pow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = 1;
        for (int i = 0; i < T; i++) {
            solve(sc);
        }
    }

    private static void solve(Scanner sc) {
        long P = sc.nextLong();
        long K = sc.nextLong();
        long MOD = 1000000007;

        if (K == 0) {
            System.out.println(modPow(P, P - 1, MOD));
            return;
        }

        // Build the mapping: x -> (K * x) % P
        int[] mapping = new int[(int) P];
        for (int x = 0; x < P; x++) {
            mapping[x] = (int) ((K * x) % P);
        }

        boolean[] visited = new boolean[(int) P];
        int[] cycleCounts = new int[(int) P];
        long result = 1;

        for (int start = 0; start < P; start++) {
            if (visited[start]) {
                continue;
            }

            // Trace the cycle starting from 'start'
            int length = 0;
            int current = start;
            while (!visited[current]) {
                visited[current] = true;
                current = mapping[current];
                length++;
            }

            cycleCounts[length]++;
        }

        // Compute the answer using cycle information
        for (int cycleLen = 1; cycleLen < P; cycleLen++) {
            int countOfCycles = cycleCounts[cycleLen];
            if (countOfCycles == 0) {
                continue;
            }

            long effectiveLength = (long) cycleLen * countOfCycles;
            if (cycleLen > 1) {
                effectiveLength += 1;
            }

            result = (result * modPow(effectiveLength, countOfCycles, MOD)) % MOD;
        }

        System.out.println(result);
    }

    private static long modPow(long base, long exponent, long mod) {
        long result = 1;
        base = base % mod;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
