        PrintWriter out = new PrintWriter(System.out);

        int h = in.nextInt();
        int n = in.nextInt();

        int low = 1;
        int high = 1 << h;

        int ans = 0;
        int move = 0;

        while (low < high) {
            int mid = low + ((high - low) >> 1);

            if (n <= mid) {
                if (move == 0) {
                    ans += 1;
                    move ^= 1;
                } else {
                    ans += (1 << h);
                }
                high = mid;
            } else {
                if (move == 1) {
                    ans += 1;
                    move ^= 1;
                } else {
                    ans += (1 << h);
                }
                low = mid + 1;
            }

            h -= 1;
        }

        out.println(ans);
        out.close();
    }

