public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int n = sc.nextInt();

        int[] sl = computeSl();

        int adjusted_n = n + sl[h-1];
        List<Integer> nl = buildPath(adjusted_n);

        int ans = 0;
        int cn = 1;
        boolean cp = false;

        while (cn != adjusted_n) {
            List<Integer> tnl = new ArrayList<>();
            for (int i = 0; i < h; i++) {
                tnl.add(cn);
                if (!cp) {
                    cn = cn << 1;
                } else {
                    cn = (cn << 1) + 1;
                }
                cp = !cp;
            }
            if (cn == adjusted_n) {
                ans += h;
                break;
            }

            tnl.add(cn);
            Collections.reverse(tnl);

            boolean found = false;
            for (int i = 1; i <= h && i < tnl.size() && i < nl.size(); i++) {
                if (nl.get(i).equals(tnl.get(i))) {
                    ans += sl[i-1] + h - i + 1;
                    h = i - 1;
                    cn = tnl.get(i-1);
                    if (cn == (tnl.get(i) << 1)) {
                        cn = (tnl.get(i) << 1) + 1;
                        cp = false;
                    } else {
                        cn = tnl.get(i) << 1;
                        cp = true;
                    }
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }
        }
        System.out.println(ans);
    }

    private static int[] computeSl() {
        int[] sl = new int[51];
        sl[0] = 1;
        for (int i = 1; i <= 50; i++) {
            sl[i] = sl[i-1] + (2 << (i-1));
        }
        return sl;
    }

    private static List<Integer> buildPath(int target) {
        List<Integer> path = new ArrayList<>();
        int t = target;
        while (t != 1) {
            path.add(t);
            t /= 2;
        }
        path.add(1);
        return path;
    }
}

