public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        List<Long> sl = new ArrayList<>();
        sl.add(1L);
        for (int i = 0; i < 50; i++) {
            sl.add(sl.get(sl.size() - 1) + (1L << (i + 1)));
        }

        int h = sc.nextInt();
        int n = sc.nextInt();

        List<Long> path = buildAncestry(n + sl.get(h - 1));

        long total = 0;
        long curr = 1;
        boolean flip = false;

        while (curr != n + sl.get(h - 1)) {
            List<Long> tempPath = new ArrayList<>();
            for (int j = 0; j < h; j++) {
                tempPath.add(curr);
                curr <<= 1;
                if (flip) {
                    curr += 1;
                }
                flip = !flip;
            }

            if (curr == n + sl.get(h - 1)) {
                total += h;
                break;
            }

            tempPath.add(curr);
            Collections.reverse(tempPath);

            boolean found = false;
            for (int idx = 1; idx <= h; idx++) {
                if (path.get(idx).equals(tempPath.get(idx))) {
                    total += sl.get(idx - 1) + h - idx + 1;
                    h = idx - 1;
                    curr = tempPath.get(idx - 1);

                    if (curr == (tempPath.get(idx) << 1)) {
                        curr = (tempPath.get(idx) << 1) + 1;
                        flip = false;
                    } else {
                        curr = tempPath.get(idx) << 1;
                        flip = true;
                    }
                    found = true;
                    break;
                }
            }

            if (!found) {
                break;
            }
        }

        System.out.println(total);
    }

    private static List<Long> buildAncestry(long x) {
        List<Long> path = new ArrayList<>();
        path.add(x);
        while (x > 1) {
            x >>= 1;
            path.add(x);
        }
        return path;
    }
}

