            n_val /= 2;
            nl.add(n_val);
        }

        int total_steps = 0;
        int current = 1;
        boolean parity = false;

        while (current != nl.get(nl.size() - 1)) {
            List<Integer> temp_path = new ArrayList<>();
            for (int j = 0; j < h; j++) {
                temp_path.add(current);
                if (parity) {
                    current = (current << 1) + 1;
                } else {
                    current <<= 1;
                }
                parity ^= true;
            }
            if (current == nl.get(nl.size() - 1)) {
                total_steps += h;
                break;
            }

            temp_path.add(current);
            Collections.reverse(temp_path);
            boolean found = false;
            for (int i = 1; i <= h; i++) {
                if (nl.get(i).equals(temp_path.get(i))) {
                    total_steps += sl[i-1] + h - i + 1;
