                    current = temp_path.get(i-1);
                    if (current == (temp_path.get(i) << 1)) {
                        current = (temp_path.get(i) << 1) + 1;
                        parity = false;
                    } else {
                        current = temp_path.get(i) << 1;
                        parity = true;
                    }
                    found = true;
                    break;
                }
            }
