                s += nBin.charAt(i);
            }
        }

        int ct = 0;
        for (int i = 0; i < h; i++) {
            ct += 1;
            if (s.charAt(i) == '1') {
                ct += (1 << (h - i)) - 1;
            }
        }
        System.out.println(ct);
    }
}

