import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();

        // Replace first occurrence of 'at' with '@' starting from index 1
        int atIndex = s.indexOf("at", 1);
        if (atIndex != -1) {
            s = s.substring(0, atIndex) + "@" + s.substring(atIndex + 2);
        }

        // Replace first occurrence of 'dot' with '.' in the middle part (excluding first and last char)
        if (s.length() >= 2) {
            String middle = s.substring(1, s.length() - 1);
            int dotIndex = middle.indexOf("dot");
            if (dotIndex != -1) {
                String result = s.charAt(0) + 
                               middle.substring(0, dotIndex) + "." + 
                               middle.substring(dotIndex + 3) + 
                               s.charAt(s.length() - 1);
                System.out.println(result);
                return;
            }
        }

        // If no replacement happened in the middle, print original with last char
        System.out.println(s);
    }
}

