import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // Replace all occurrences of "dot" (except at the very start or end) with '.'
        while (true) {
            Pattern pattern = Pattern.compile("(?<!^)dot(?!$)");
            Matcher matcher = pattern.matcher(s);
            if (!matcher.find()) {
                break;
            }
            int pos = matcher.start();
            s = s.substring(0, pos) + '.' + s.substring(pos + 3);
        }

        // Replace first occurrence of "at" (except at the very start or end) with '@'
        Pattern pattern = Pattern.compile("(?<!^)at(?!$)");
        Matcher matcher = pattern.matcher(s);
        if (matcher.find()) {
            int pos = matcher.start();
            s = s.substring(0, pos) + '@' + s.substring(pos + 2);
        }

        System.out.println(s);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // Replace all "dot" substrings (excluding first and last character positions)
        char[] parts = s.toCharArray();
        int i = 1;
        while (i < parts.length - 3) {
            if (parts[i] == 'd' && parts[i+1] == 'o' && parts[i+2] == 't') {
                parts[i] = '.';
                // Shift remaining characters left by 2 positions
                for (int j = i + 3; j < parts.length; j++) {
                    parts[j - 2] = parts[j];
                }
                // Reduce effective length by 2
                parts = Arrays.copyOf(parts, parts.length - 2);
            } else {
                i++;
            }
        }

        s = new String(parts);

        // Replace first "at" substring (excluding first and last character positions)
        parts = s.toCharArray();
        i = 1;
        while (i < parts.length - 2) {
            if (parts[i] == 'a' && parts[i+1] == 't') {
                parts[i] = '@';
                // Shift remaining characters left by 1 position
                for (int j = i + 2; j < parts.length; j++) {
                    parts[j - 1] = parts[j];
                }
                // Reduce effective length by 1
                parts = Arrays.copyOf(parts, parts.length - 1);
                break;
            } else {
                i++;
            }
        }

        s = new String(parts);
        System.out.println(s);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // Replace all occurrences of "dot" with '.' (excluding first and last char)
        while (true) {
            int idx = s.indexOf("dot", 1);
            if (idx == -1 || idx + 3 >= s.length()) {
                break;
            }
            s = s.substring(0, idx) + "." + s.substring(idx + 3);
        }

        // Replace first occurrence of "at" with '@' (excluding first and last char)
        int idx = s.indexOf("at", 1);
        if (idx != -1 && idx + 2 < s.length()) {
            s = s.substring(0, idx) + "@" + s.substring(idx + 2);
        }

        System.out.println(s);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // Process "dot" replacements using string splitting
        while (true) {
            if (s.length() < 4) {
                break;
            }
            // Find "dot" not at boundaries
            boolean found = false;
            for (int i = 1; i <= s.length() - 3; i++) {
                if (s.substring(i, i + 3).equals("dot")) {
                    s = s.substring(0, i) + '.' + s.substring(i + 3);
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }
        }

        // Process first "at" replacement
        for (int i = 1; i <= s.length() - 2; i++) {
            if (s.substring(i, i + 2).equals("at")) {
                s = s.substring(0, i) + '@' + s.substring(i + 2);
                break;
            }
        }

        System.out.println(s);
    }
}

