import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // Replace 'dot' with '.' when surrounded by characters
        Pattern dotPattern = Pattern.compile("(?<=.)(dot)(?=.)");
        Matcher dotMatcher = dotPattern.matcher(s);
        s = dotMatcher.replaceAll(".");

        // Replace first occurrence of 'at' with '@' when surrounded by characters
        Pattern atPattern = Pattern.compile("(?<=.)(at)(?=.)");
        Matcher atMatcher = atPattern.matcher(s);
        s = atMatcher.replaceFirst("@");

        System.out.println(s);
    }
}

