            s = d + s.substring(1);
        }

        // Check if last character is a dot, replace with 'dot'
        if (s.length() > 0 && s.charAt(s.length() - 1) == '.') {
            s = s.substring(0, s.length() - 1) + d;
        }

        System.out.println(s);
    }
}

