public class Main {
    public static String transformString() {
        String dot = "dot";

        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine().replace(dot, ".");

        // Process the string: keep first char, replace 'at' with '@' once in the rest
        String firstChar = s.substring(0, 1);
        String rest = s.substring(1);
        rest = rest.replaceFirst("at", "@");
        s = firstChar + rest;

        // Handle leading dot
        if (s.startsWith(".")) {
            s = dot + s.substring(1);
        }

        // Handle trailing dot
        if (s.endsWith(".")) {
            s = s.substring(0, s.length() - 1) + dot;
        }

        return s;
    }

    public static void main(String[] args) {
        System.out.println(transformString());
    }
}

