        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // First replacement: replace first occurrence of 'at' with '@'
        s = s.replaceFirst("at", "@");

        // If the string starts with '@', handle special case
        if (s.startsWith("@")) {
            // Replace the first '@' back to 'at' and then replace next 'at' with '@'
            s = "at" + s.substring(1).replaceFirst("at", "@");
        }

        // Handle 'dot' replacements
        if (s.contains("dot")) {
            s = s.replace("dot", ".");
            // If starts with '.', replace first '.' back to 'dot'
            if (s.startsWith(".")) {
                s = s.replaceFirst("\\.", "dot");
            }
            // If ends with '.', replace last '.' with 'dot'
            if (s.endsWith(".")) {
                s = s.substring(0, s.length() - 1) + "dot";
            }
        }

        System.out.println(s);
    }
}

