import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[20];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        List<Integer> b = new ArrayList<>();
        int halfSize1 = n / 2 + n % 2;

        for (int i = 0; i < (1 << halfSize1); i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) == 1) {
                    t += a[j];
                }
                k = k >> 1;
            }
            b.add(t % m);
        }

        Collections.sort(b);

        int otv = 0;
        int halfSize2 = n / 2;

        for (int i = 0; i < (1 << halfSize2); i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) == 1) {
                    t += a[halfSize1 + j];
                }
                k = k >> 1;
            }
            t = t % m;

            int target = m - t - 1;
            int k = Collections.binarySearch(b, target);
            if (k < 0) {
                k = -(k + 1);
            }

            int t2 = 0;
            if (k < b.size()) {
                t2 = b.get(k);
                if (t2 > target) {
                    if (k - 1 >= 0) {
                        t2 = b.get(k - 1);
                    }
                }
            } else {
                t2 = b.get(b.size() - 1);
            }

            int candidate1 = (t + t2) % m;
            int candidate2 = (t + b.get(b.size() - 1)) % m;
            otv = Math.max(otv, Math.max(candidate1, candidate2));
        }

        System.out.println(otv % m);
    }
}

