            exploreLeft(values, index + 1, (current + values[index]) % m, split_point, m, left_vals);
            exploreLeft(values, index + 1, current, split_point, m, left_vals);
        }
    }

    private static void exploreRight(int[] values, int index, int current, int n, int m, List<Integer> right_vals) {
