        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int n1 = n / 2;
        List<Integer> leftSums = new ArrayList<>();
        List<Integer> rightSums = new ArrayList<>();

        computeSums(a, 0, n1, m, leftSums);
        computeSums(a, n1, n, m, rightSums);

        int ans = 0;
        Set<Integer> leftSet = new HashSet<>(leftSums);
        List<Integer> leftList = new ArrayList<>(leftSet);
        Collections.sort(leftList);

        for (int rVal : rightSums) {
            int complement = (m - rVal) % m;
            int idx = Collections.binarySearch(leftList, complement);
            if (idx < 0) {
                idx = -idx - 1;
            }

            if (idx > 0) {
                int candidate = (leftList.get(idx - 1) + rVal) % m;
                ans = Math.max(ans, candidate);
            }
            if (idx < leftList.size()) {
                int candidate = (leftList.get(idx) + rVal) % m;
                ans = Math.max(ans, candidate);
            }
        }

        System.out.println(ans);
    }

    private static void computeSums(int[] arr, int start, int end, int m, List<Integer> resultList) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{start, 0});

        while (!stack.isEmpty()) {
            int[] current = stack.pop();
            int idx = current[0];
            int s = current[1];

            if (idx == end) {
                resultList.add(s % m);
            } else {
                stack.push(new int[]{idx + 1, (s + arr[idx]) % m});
                stack.push(new int[]{idx + 1, s});
            }
        }
    }
}

