    private static List<Integer> getSubsequenceSums(int[] arr, int mod) {
        Set<Integer> res = new HashSet<>();
        backtrack(arr, 0, 0, mod, res);
        List<Integer> sorted = new ArrayList<>(res);
        Collections.sort(sorted);
        return sorted;
    }

    private static void backtrack(int[] arr, int i, int cur, int mod, Set<Integer> res) {
        if (i == arr.length) {
            res.add(cur % mod);
            return;
        }
        backtrack(arr, i + 1, cur + arr[i], mod, res);
        backtrack(arr, i + 1, cur, mod, res);
    }
}

