        dfsLeft(a, n1, m, i + 1, s, a1);
    }

    private static void dfsRight(int[] a, int n, int m, int i, int s, List<Integer> a2) {
        if (i == n) {
            a2.add(s);
            return;
        }
        dfsRight(a, n, m, i + 1, (s + a[i]) % m, a2);
        dfsRight(a, n, m, i + 1, s, a2);
    }

    private static int binarySearch(List<Integer> list, int target) {
        int left = 0;
        int right = list.size() - 1;
        while (left <= right) {
            int mid = (left + right) / 2;
            if (list.get(mid) == target) {
                return mid;
            } else if (list.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -left - 1;
    }
}

