public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);

        String[] secondLine = br.readLine().split(" ");
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(secondLine[i]) % m;
        }

        int half = n / 2;
        int[] leftPart = new int[half];
        int[] rightPart = new int[n - half];

        System.arraycopy(arr, 0, leftPart, 0, half);
        System.arraycopy(arr, half, rightPart, 0, n - half);

        Set<Integer> leftSums = getAllSumsModulo(leftPart, m);
        Set<Integer> rightSums = getAllSumsModulo(rightPart, m);

        List<Integer> rightSorted = new ArrayList<>(rightSums);
        Collections.sort(rightSorted);

        int maxSum = 0;

        for (int ls : leftSums) {
            int target = m - ls;
            int idx = binarySearchLeftmost(rightSorted, target);

            for (int j : new int[]{idx - 1, idx}) {
                if (j >= 0 && j < rightSorted.size()) {
                    int candidate = ls + rightSorted.get(j);
                    if (candidate > maxSum) {
                        maxSum = candidate;
                    }
                }
            }
        }

        System.out.println(maxSum);
    }

    private static Set<Integer> getAllSumsModulo(int[] subarr, int mod) {
        Set<Integer> result = new HashSet<>();
        result.add(0);

        int n = subarr.length;
        for (int length = 1; length <= n; length++) {
            int[] indices = new int[length];
            for (int i = 0; i < length; i++) {
                indices[i] = i;
            }

            while (true) {
                int total = 0;
                for (int idx : indices) {
                    total += subarr[idx];
                }
                total %= mod;
                result.add(total);

                // Generate next combination
                int i = length - 1;
                while (i >= 0 && indices[i] == n - length + i) {
                    i--;
                }

                if (i < 0) {
                    break;
                }

                indices[i]++;
                for (int j = i + 1; j < length; j++) {
                    indices[j] = indices[j - 1] + 1;
                }
            }
        }

        return result;
    }

    private static int binarySearchLeftmost(List<Integer> list, int target) {
        int left = 0;
        int right = list.size();

        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid) < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }
}

