public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt() % m;
        }

        int mid = n / 2;
        Set<Integer> leftSums = computeSums(Arrays.copyOfRange(a, 0, mid), m);
        Set<Integer> rightSums = computeSums(Arrays.copyOfRange(a, mid, n), m);

        List<Integer> rightList = new ArrayList<>(rightSums);
        Collections.sort(rightList);
        int best = 0;

        for (int s : leftSums) {
            int needed = m - s;
            int pos = Collections.binarySearch(rightList, needed);
            if (pos < 0) {
                pos = -pos - 1;
            }
            for (int offset = -1; offset <= 0; offset++) {
                if (0 <= pos + offset && pos + offset < rightList.size()) {
                    int total = s + rightList.get(pos + offset);
                    if (total > best) {
                        best = total;
                    }
                }
            }
        }

        System.out.println(best);
    }

    private static Set<Integer> computeSums(int[] arr, int mod) {
        Set<Integer> sums = new HashSet<>();
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0});

        while (!stack.isEmpty()) {
            int[] item = stack.pop();
            int idx = item[0];
            int curSum = item[1];

            if (idx == arr.length) {
                sums.add(curSum % mod);
            } else {
                stack.push(new int[]{idx + 1, (curSum + arr[idx]) % mod});
                stack.push(new int[]{idx + 1, curSum});
            }
        }

        return sums;
    }
}

