                    s += left_part[j];
                }
            }
            left_mods.add(s % m);
        }

        List<Integer> right_mods = new ArrayList<>();
        for (int i = 0; i < (1 << right_len); i++) {
            int s = 0;
            for (int j = 0; j < right_len; j++) {
                if ((i >> j & 1) == 1) {
                    s += right_part[j];
                }
            }
            right_mods.add(s % m);
        }

        Collections.sort(left_mods);
        Collections.sort(right_mods);

        int best = 0;

        for (int a : left_mods) {
            int target = m - a;
            int b = findMaxLessThan(right_mods, target);
            int candidate = (a + b) % m;
            if (candidate > best) {
                best = candidate;
            }
        }

        System.out.println(best);
    }

    private static int findMaxLessThan(List<Integer> arr, int limit) {
        int lo = 0;
        int hi = arr.size() - 1;
        int res = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (arr.get(mid) < limit) {
                res = arr.get(mid);
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return res;
    }
