    private static List<Integer> generateSubseqSums(int[] arr, int mod) {
        List<Integer> sums = new ArrayList<>();
        sums.add(0);

        for (int val : arr) {
            List<Integer> newSums = new ArrayList<>();
            for (int s : sums) {
                newSums.add((s + val) % mod);
            }
            sums.addAll(newSums);
        }

        return sums;
    }

    private static int solve(List<Integer> a1, int m, int x) {
        int idx = binarySearch(a1, m - x);
        if (idx > 0) {
            return a1.get(idx - 1) + x;
        }
        return x;
    }

    private static int binarySearch(List<Integer> list, int target) {
        int left = 0;
        int right = list.size();

        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid) >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        return left;
    }
