        }

        int n1 = n / 2;
        List<Integer> a1_mods = getModularSums(a, 0, n1, m);
        List<Integer> a2_mods = getModularSums(a, n1, n - n1, m);

        Set<Integer> a1Set = new HashSet<>(a1_mods);
        List<Integer> a1UniqueSorted = new ArrayList<>(a1Set);
        Collections.sort(a1UniqueSorted);

        List<Integer> results = new ArrayList<>();
        for (int val : a2_mods) {
            results.add(findBestPair(val, a1UniqueSorted, m));
        }

        int maxResult = Collections.max(results);
        System.out.println(maxResult);
    }

    private static List<Integer> getModularSums(int[] arr, int start, int length, int mod) {
        List<Integer> res = new ArrayList<>();
        int[] elements = new int[length];
        for (int i = 0; i < length; i++) {
            elements[i] = arr[start + i];
        }

        int n = length;
        for (int r = 0; r <= n; r++) {
            int[] combination = new int[r];
            combine(elements, 0, 0, r, combination, res, mod);
        }

        return res;
    }

    private static void combine(int[] arr, int start, int index, int r, int[] combination, List<Integer> res, int mod) {
        if (index == r) {
            int sum = 0;
            for (int i = 0; i < r; i++) {
                sum += combination[i];
            }
            res.add(sum % mod);
            return;
        }

        for (int i = start; i < arr.length; i++) {
            combination[index] = arr[i];
            combine(arr, i + 1, index + 1, r, combination, res, mod);
        }
    }

    private static int findBestPair(int x, List<Integer> sortedList, int m) {
        int target = m - x;
        int idx = Collections.binarySearch(sortedList, target);
        if (idx < 0) {
            idx = -idx - 1;
        }

        if (idx == 0) {
            return x;
        }

        return sortedList.get(idx - 1) + x;
    }
}

