    static class Factorial {
        int MOD;
        List<Long> factorials;
        List<Long> invModulos;
        List<Long> invFactorial_;

        Factorial(int MOD) {
            this.MOD = MOD;
            factorials = new ArrayList<>();
            factorials.add(1L);
            factorials.add(1L);
            invModulos = new ArrayList<>();
            invModulos.add(0L);
            invModulos.add(1L);
            invFactorial_ = new ArrayList<>();
            invFactorial_.add(1L);
            invFactorial_.add(1L);
        }

        long calc(int n) {
            if (n <= -1) {
                System.out.println("Invalid argument to calculate n!");
                System.out.println("n must be non-negative value. But the argument was " + n);
                System.exit(0);
            }
            if (n < factorials.size()) {
                return factorials.get(n);
            }
            for (int i = factorials.size(); i <= n; i++) {
                factorials.add(factorials.get(i - 1) * i % MOD);
            }
            return factorials.get(n);
        }

        long inv(int n) {
            if (n <= -1) {
                System.out.println("Invalid argument to calculate n^(-1)");
                System.out.println("n must be non-negative value. But the argument was " + n);
                System.exit(0);
            }
            int p = MOD;
            int pi = n % p;
            if (pi < invModulos.size()) {
                return invModulos.get(pi);
            }
            for (int i = invModulos.size(); i < Math.min(p, n + 1); i++) {
                long next = -invModulos.get(p % i) * (p / i) % p;
                if (next < 0) next += p;
                invModulos.add(next);
            }
            return invModulos.get(pi);
        }

        long invFactorial(int n) {
            if (n <= -1) {
                System.out.println("Invalid argument to calculate (n^(-1))!");
                System.out.println("n must be non-negative value. But the argument was " + n);
                System.exit(0);
            }
            if (n < invFactorial_.size()) {
                return invFactorial_.get(n);
            }
            inv(n);
            for (int i = invFactorial_.size(); i <= n; i++) {
                long prev = invFactorial_.get(i - 1);
                long inv_i = invModulos.get(i % MOD);
                invFactorial_.add(prev * inv_i % MOD);
            }
            return invFactorial_.get(n);
        }
    }

    static class Combination {
        int MOD;
        Factorial factorial;

        Combination(int MOD) {
            this.MOD = MOD;
            factorial = new Factorial(MOD);
        }

        long ncr(int n, int k) {
            if (k < 0 || n < k) {
                return 0;
            }
            k = Math.min(k, n - k);
            Factorial f = factorial;
            return f.calc(n) * f.invFactorial(Math.max(n - k, k)) % MOD * f.invFactorial(Math.min(k, n - k)) % MOD;
        }
    }

    static long powm(long a, long n, long m) {
        if (a == 1 || n == 0) {
            return 1;
        }
        if (n % 2 == 0) {
            long s = powm(a, n / 2, m);
            return s * s % m;
        } else {
            return a * powm(a, n - 1, m) % m;
        }
    }

    static int binarySearchCount(int[] arr, int n, int key) {
        int left = 0;
        int right = n - 1;
        int count = 0;
        while (left <= right) {
            int mid = (right + left) / 2;
            if (arr[mid] <= key) {
                count = mid + 1;
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return count;
    }

