                    int v = Kij.get(k);
                    for (int h = 0; h < i + 1; h++) {
                        int val = Ki_.get(j + h).get(k);
                        Ki_.get(j + h).set(k, (val + v) % M);
                    }
                    int val = Ki_.get(j + i + 1).get(i + 1);
                    Ki_.get(j + i + 1).set(i + 1, (val + v) % M);
                }
            }
        }

        int[] C = tf(n, M);
        int s = 0;

        for (int i = 1; i < n; i++) {
            List<List<Integer>> Ki = K.get(i);
            int ni = Ki.size();
            int mi = Ki.get(0).size();

            int[][] Si = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                Si[j][mi - 1] = Ki.get(j).get(mi - 1);
                for (int k = mi - 2; k >= 0; k--) {
                    Si[j][k] = (Ki.get(j).get(k) + Si[j][k + 1]) % M;
                }
            }

            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    Si[j][k] = (Si[j][k] + Si[j - 1][k]) % M;
                }
            }

            int si = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    si = (si + (Ki.get(j).get(k) * Si[j - 1][k + 1]) % M) % M;
                }
            }

            int c = C[i + 1];
            si = (si * c) % M;
            s = (s + si) % M;
        }

        return s;
    }

    static int[] tf(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (int) ((long) C[k + 1] * (k + 1) % M);
            if (C[k] == 0) {
                break;
            }
        }
        return C;
    }
}

