import java.util.*;
import java.io.*;

public class Main {
    static long MOD;

    static long factorial(long n) {
        long res = 1;
        for (long i = 2; i <= n; i++) {
            res = (res * i) % MOD;
        }
        return res;
    }

    static long A(long n, long k) {
        long res = 1;
        for (long i = n; i > n - k; i--) {
            res = (res * i) % MOD;
        }
        return res;
    }

    public static void solve() {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        MOD = sc.nextLong();

        if (n == 1) {
            System.out.println(0);
            return;
        }

        List<Long> z = new ArrayList<>();
        z.add(1L);

        long aaa = 0;

        for (long i = 2; i <= n; i++) {
            int newZSize = (int) ((i - 1) * i / 2 + 1);
            List<Long> nz = new ArrayList<>(Collections.nCopies(newZSize, 0L));

            List<Long> d = new ArrayList<>(Collections.nCopies(z.size() + 1, 0L));
            for (int w = z.size() - 1; w >= 0; w--) {
                d.set(w, (d.get(w + 1) + z.get(w)) % MOD);
            }

            for (int w = 0; w < newZSize; w++) {
                int L = Math.max(0, w + 1 - (int) i);
                int R = Math.min(z.size() - 1, w);
                long val = (d.get(L) - d.get(R + 1)) % MOD;
                if (val < 0) val += MOD;
                nz.set(w, val);
            }

            List<Long> e = new ArrayList<>(Collections.nCopies(d.size() + 1, 0L));
            List<Long> f = new ArrayList<>(Collections.nCopies(d.size() + 1, 0L));

            for (int w = 0; w < d.size(); w++) {
                e.set(w + 1, (e.get(w) + d.get(w)) % MOD);
                long term = (w * d.get(w)) % MOD;
                f.set(w + 1, (f.get(w) - term) % MOD);
                if (f.get(w + 1) < 0) f.set(w + 1, f.get(w + 1) + MOD);
            }

            int R = z.size();
            long bbb = 0;

            for (int jj = Math.max(0, z.size() - (int) i); jj < z.size() - 2; jj++) {
                int L = jj + 2;
                long term1 = (e.get(R) - e.get(L)) % MOD;
                long term2 = (f.get(R) - f.get(L)) % MOD;
                if (term1 < 0) term1 += MOD;
                if (term2 < 0) term2 += MOD;
                long multiplier = (term1 * (i + 1 + jj) + term2) % MOD;
                bbb = (bbb + multiplier * z.get(jj)) % MOD;
            }

            for (int jj = 0; jj < z.size() - (int) i; jj++) {
                int L = jj + 2;
                int R2 = (int) i + jj;
                long term1 = (e.get(R2 + 1) - e.get(L)) % MOD;
                long term2 = (f.get(R2 + 1) - f.get(L)) % MOD;
                if (term1 < 0) term1 += MOD;
                if (term2 < 0) term2 += MOD;
                long multiplier = (term1 * (i + 1 + jj) + term2) % MOD;
                bbb = (bbb + multiplier * z.get(jj)) % MOD;
            }

            aaa = (aaa + (bbb * A(n, n - i)) % MOD) % MOD;
            z = nz;
        }

        System.out.println(aaa % MOD);
    }

    public static void main(String[] args) {
        solve();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static long MOD = 0;

    static long factorial(long n) {
        long result = 1;
        for (long i = 2; i <= n; i++) {
            result = (result * i) % MOD;
        }
        return result;
    }

    static long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long A(long n, long k) {
        long numerator = factorial(n);
        long denominator = factorial(n - k);
        return (numerator * modInverse(denominator, MOD)) % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        long n = Long.parseLong(line[0]);
        MOD = Long.parseLong(line[1]);

        if (n == 1) {
            System.out.println(0);
            return;
        }

        List<Long> z = new ArrayList<>();
        z.add(1L);

        long total = 0;

        for (long i = 2; i <= n; i++) {
            int newZSize = (int) ((i - 1) * i / 2 + 1);
            List<Long> new_z = new ArrayList<>(Collections.nCopies(newZSize, 0L));

            // Compute prefix sums d for z
            List<Long> d = new ArrayList<>(Collections.nCopies(z.size() + 1, 0L));
            for (int w = z.size() - 1; w >= 0; w--) {
                d.set(w, (d.get(w + 1) + z.get(w)) % MOD);
            }

            // Fill new_z using d
            for (int w = 0; w < newZSize; w++) {
                int L = Math.max(0, w + 1 - (int) i);
                int R = Math.min(z.size() - 1, w);
                long val = (d.get(L) - d.get(R + 1)) % MOD;
                if (val < 0) val += MOD;
                new_z.set(w, val);
            }

            // Compute prefix sums e and weighted prefix sums f
            List<Long> e = new ArrayList<>(Collections.nCopies(d.size() + 1, 0L));
            List<Long> f = new ArrayList<>(Collections.nCopies(d.size() + 1, 0L));
            for (int w = 0; w < e.size() - 1; w++) {
                e.set(w + 1, (e.get(w) + d.get(w)) % MOD);
                long term = (w * d.get(w)) % MOD;
                f.set(w + 1, (f.get(w) - term) % MOD);
                if (f.get(w + 1) < 0) f.set(w + 1, f.get(w + 1) + MOD);
            }

            // Compute contribution bbb
            long bbb = 0;
            int R = z.size();

            // First loop
            for (int jj = Math.max(0, z.size() - (int) i); jj < z.size() - 2; jj++) {
                int L = jj + 2;
                long term1 = (e.get(R) - e.get(L)) % MOD;
                long term2 = (f.get(R) - f.get(L)) % MOD;
                if (term1 < 0) term1 += MOD;
                if (term2 < 0) term2 += MOD;
                long term = (term1 * ((i + 1 + jj) % MOD)) % MOD;
                term = (term + term2) % MOD;
                term = (term * z.get(jj)) % MOD;
                bbb = (bbb + term) % MOD;
            }

            // Second loop
            for (int jj = 0; jj < z.size() - (int) i; jj++) {
                int L = jj + 2;
                int R2 = (int) i + jj;
                long term1 = (e.get(R2 + 1) - e.get(L)) % MOD;
                long term2 = (f.get(R2 + 1) - f.get(L)) % MOD;
                if (term1 < 0) term1 += MOD;
                if (term2 < 0) term2 += MOD;
                long term = (term1 * ((i + 1 + jj) % MOD)) % MOD;
                term = (term + term2) % MOD;
                term = (term * z.get(jj)) % MOD;
                bbb = (bbb + term) % MOD;
            }

            long contrib = (bbb * A(n, n - i)) % MOD;
            total = (total + contrib) % MOD;

            z = new_z;
        }

        System.out.println(total % MOD);
    }
}

