    public static long solve(long n, long mod) {
        long m = n * (n - 1) / 2;

        // Use 2D arrays but allocated dynamically for required ranges
        long max_bound = n * (n - 1) + 1;

        long[][] dp = new long[(int)n + 1][(int)max_bound];
        long[][] dp1 = new long[(int)n + 1][(int)max_bound];

        dp[1][(int)m] = 1;

        // Iterate through all levels
        for (long i = 2; i <= n; i++) {
            long[] bounds = getBounds(i, m);
            long low = bounds[0];
            long high = bounds[1];

            for (long x = low; x <= high; x++) {
                if (dp[(int)(i-1)][(int)x] == 0) continue;
                long base_val = dp[(int)(i-1)][(int)x];

                for (long d = -i + 1; d < i; d++) {
                    dp[(int)i][(int)(x + d)] = (dp[(int)i][(int)(x + d)] + base_val * (i - Math.abs(d))) % mod;
                }
            }

            // Process dp1 for this level
            long[] boundsPrev = getBounds(i-1, m);
            long lowPrev = boundsPrev[0];
            long highPrev = boundsPrev[1];

            // Multiply previous dp1 by i
            for (long x = lowPrev; x <= highPrev; x++) {
                if (dp1[(int)(i-1)][(int)x] != 0) {
                    dp1[(int)i][(int)x] = (dp1[(int)i][(int)x] + dp1[(int)(i-1)][(int)x] * i) % mod;
                }
            }

            // Add contributions from dp[i-1]
            for (long x = lowPrev; x <= highPrev; x++) {
                if (dp[(int)(i-1)][(int)x] == 0) continue;
                long base_val = dp[(int)(i-1)][(int)x];

                for (long d = 1; d < i; d++) {
                    dp1[(int)i][(int)(x - d)] = (dp1[(int)i][(int)(x - d)] + base_val * (i - d)) % mod;
                }
            }
        }

        // Calculate result as sum of dp1[n][x] for x > m
        long result = 0;
        for (long x = m + 1; x <= n * (n - 1); x++) {
            result = (result + dp1[(int)n][(int)x]) % mod;
        }
        return result;
    }

    private static long[] getBounds(long i, long m) {
        long span = (i - 1) * (i - 2) / 2;
        return new long[]{m - span, m + span};
    }
}

