import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();
        Map<List<Integer>, Long> memo = new HashMap<>();
        long result = go(n, n, memo) - go(n, Math.max(0, h - 1), memo);
        System.out.println(result);
    }

    public static long go(int n, int h, Map<List<Integer>, Long> v) {
        List<Integer> key = Arrays.asList(n, h);
        if (!v.containsKey(key)) {
            if (n == 0) {
                v.put(key, 1L);
            } else if (h == 0) {
                v.put(key, 0L);
            } else {
                long sum = 0;
                for (int i = 0; i < n; i++) {
                    long left = go(i, h - 1, v);
                    long right = go(n - 1 - i, h - 1, v);
                    sum += left * right;
                }
                v.put(key, sum);
            }
        }
        return v.get(key);
    }
}

