import java.util.Scanner;

public class Main {
    static int[][] dp;

    static int t(int n, int h) {
        if (dp[n][h] == -1) {
            int sum = 0;
            for (int m = 1; m <= n; m++) {
                int term1 = t(m - 1, h - 1);
                int innerSum1 = 0;
                for (int i = 0; i < h; i++) {
                    innerSum1 += t(n - m, i);
                }

                int term2 = t(n - m, h - 1);
                int innerSum2 = 0;
                for (int i = 0; i < h - 1; i++) {
                    innerSum2 += t(m - 1, i);
                }

                sum += term1 * innerSum1 + term2 * innerSum2;
            }
            dp[n][h] = sum;
        }
        return dp[n][h];
    }

    static int fill(int i, int j) {
        if (i == 0 && j == 0) {
            return 1;
        }

        if (i == 0 || j == 0) {
            return 0;
        }

        return -1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        dp = new int[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = fill(i, j);
            }
