        long[][] dp = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1);
        }
        dp[0][0] = 1;

        long finalResult = recursiveF(n, h, dp, n);
        System.out.println(finalResult);
    }

    private static long recursiveF(int nVal, int hVal, long[][] dp, int maxN) {
        if (dp[nVal][hVal] != -1) {
            return dp[nVal][hVal];
        }

        if (nVal == 0) {
            dp[nVal][hVal] = 0;
            return 0;
        }
        if (hVal == 0) {
            dp[nVal][hVal] = recursiveF(nVal, 1, dp, maxN);
            return dp[nVal][hVal];
        }

        long total = 0;
        for (int idx = 0; idx < nVal; idx++) {
            long part1 = recursiveF(nVal - idx - 1, 0, dp, maxN) * recursiveF(idx, hVal - 1, dp, maxN);
            long part2 = recursiveF(nVal - idx - 1, hVal - 1, dp, maxN) * recursiveF(idx, 0, dp, maxN);
            long part3 = recursiveF(nVal - idx - 1, hVal - 1, dp, maxN) * recursiveF(idx, hVal - 1, dp, maxN);
            total += part1 + part2 - part3;
        }

        dp[nVal][hVal] = total;
        return total;
    }
}

